{
  "ok": true,
  "anomalies": [
    {
      "rule": "text_ratio_is_a_percentage",
      "message": "text ratio exceeds 100%: the text and the size were not measured alike",
      "observed": 150.0,
      "expected": "<= 100",
      "target": "https://ex.org/a",
      "sources": {
        "observed": "pages.jsonl:text_ratio"
      }
    },
    {
      "rule": "words_without_bytes",
      "message": "words were counted on a page recorded as zero bytes",
      "observed": 9,
      "expected": 0,
      "target": "https://ex.org/b",
      "sources": {
        "observed": "pages.jsonl:word_count",
        "expected": "pages.jsonl:size_bytes"
      }
    },
    {
      "rule": "findings_are_about_crawled_urls",
      "message": "TITLE_MISSING reports a URL absent from this run's own page list",
      "observed": "https://ex.org/absent",
      "expected": "a URL in pages.jsonl",
      "target": "https://ex.org/absent",
      "sources": {
        "observed": "audit.json:issues",
        "expected": "pages.jsonl:url"
      }
    },
    {
      "rule": "check_within_its_population",
      "message": "X_BIG fired more often than there are HTML pages to fire on",
      "observed": 5,
      "expected": 3,
      "target": "X_BIG",
      "sources": {
        "observed": "audit.json:summary.by_check",
        "expected": "pages.jsonl: pages with an HTML content type"
      }
    },
    {
      "rule": "summary_matches_detail",
      "message": "summary claims 5 X_BIG findings, the issue list holds 0",
      "observed": 5,
      "expected": 0,
      "target": "X_BIG",
      "sources": {
        "observed": "audit.json:summary.by_check",
        "expected": "audit.json:issues"
      }
    },
    {
      "rule": "canonical_to_redirect_has_no_answering_twin",
      "message": "canonical reported as a redirect, but that URL answered 2xx in this run",
      "observed": "3xx",
      "expected": "2xx",
      "target": "https://ex.org/c/",
      "sources": {
        "observed": "audit.json:issues[CANONICAL_TO_REDIRECT]",
        "expected": "pages.jsonl:status_code"
      }
    },
    {
      "rule": "outside_host_exclusion_matches_its_own_host",
      "message": "excluded as outside_host, but its host is the crawl's own host",
      "observed": "ex.org",
      "expected": "a host other than 'ex.org'",
      "target": "https://ex.org/off",
      "sources": {
        "observed": "decisions.jsonl:url",
        "expected": "decisions.jsonl:host"
      }
    },
    {
      "rule": "representation_is_recorded",
      "message": "some pages record how they were measured and some do not",
      "observed": 1,
      "expected": 0,
      "target": "",
      "sources": {
        "observed": "pages.jsonl:representation"
      }
    }
  ],
  "anomaly_count": 8,
  "review": [
    {
      "rule": "check_describes_most_of_the_site",
      "message": "X_BIG describes 90% of the crawled pages -- true of some sites, and what a broken check looks like on the rest",
      "observed": 9,
      "expected": "under 50% of pages, for a check about the unusual",
      "target": "X_BIG",
      "sources": {
        "observed": "audit.json:summary.implausible_checks"
      }
    }
  ],
  "by_rule": {
    "text_ratio_is_a_percentage": 1,
    "words_without_bytes": 1,
    "findings_are_about_crawled_urls": 1,
    "check_within_its_population": 1,
    "summary_matches_detail": 1,
    "canonical_to_redirect_has_no_answering_twin": 1,
    "outside_host_exclusion_matches_its_own_host": 1,
    "representation_is_recorded": 1
  },
  "read": {
    "audit": true,
    "pages": 3,
    "downloaded_files": 0,
    "decisions": 3
  },
  "rules_run": [
    "recorded_size_matches_the_file",
    "text_ratio_is_a_percentage",
    "a_200_has_bytes",
    "findings_are_about_crawled_urls",
    "a_check_cannot_exceed_its_population",
    "summary_matches_the_issue_rows",
    "canonical_to_redirect_has_no_answering_twin",
    "outside_host_exclusion_matches_its_own_host",
    "representation_is_recorded"
  ],
  "limitations": []
}

